insert into public.scholarships (name, funder, country, funding_type, level, criteria, award_note, deadline, link, source_url, school_id, verified, demo)
select n.name, n.funder, n.country, n.ftype, n.lvl, n.criteria, n.award, n.dl::date, n.url, n.url, s.id, false, false
from _new_ads n left join public.schools s on s.name = n.school
where (n.school is null or s.id is not null)
  and not exists (select 1 from public.scholarships x where x.name = n.name and x.school_id is not distinct from s.id and x.funder = n.funder);

drop table if exists pg_temp._new_ads;

-- Check: the new awards, fully funded first.
select funding_type, count(*) from public.scholarships where source_url like 'https://www.scholarshipsads.com/%' or criteria like '%scholarshipsads.com%' group by 1 order by 1;
